/* ==========================================================================
   plates.js — the FBI reference impressions, inlined.

   Generated, not hand-written. Each entry is the alpha channel of one
   exemplar plate from "The Science of Fingerprints" (a United States
   Government work, public domain), reduced to 256 x 256 and carried as a data
   URI. See README for the figure numbers.

   Why inline: CSS mask-image is subject to CORS, so a mask referenced by
   path is blocked when index.html is opened straight off disk as a file://
   page, and every print box comes up empty. Data URIs are exempt, so the
   bench works double-clicked as well as served.
   ========================================================================== */
(function (global) {
    "use strict";
    global.AFIS = global.AFIS || {};
    global.AFIS.PLATE_DATA = {
        "accidental": "data:image/png;base64,",
        "central-pocket": "data:image/png;base64,",
        "double-loop": "data:image/png;base64,",
        "loop": "data:image/png;base64,",
        "plain-arch": "data:image/png;base64,",
        "plain-whorl": "data:image/png;base64,",
        "tented-arch": "data:image/png;base64,"
    };
})(typeof window !== "undefined" ? window : globalThis);
